1	import React from 'react';
2	import { describe, test, expect, vi } from 'vitest';
3	import { render, screen } from '@testing-library/react';
4	import { MemoryRouter } from 'react-router-dom';
5	import { ZimmColourSwatch } from './index';
6	
7	// Provide a minimal Chakra context so chakra() and useMultiStyleConfig resolve without
8	// needing the full Zimmermann theme (which would require the ZimmColourSwatch recipe
9	// to be registered before these tests are even loaded).
10	vi.mock('@chakra-ui/react', async (importOriginal) => {
11	  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
12	  return { ...actual, useMultiStyleConfig: () => ({ swatch: {}, image: {} }) };
13	});
14	
15	const IMAGE = 'https://example.test/swatch.jpg';
16	
17	const wrap = (ui: React.ReactElement) => render(<MemoryRouter>{ui}</MemoryRouter>);
18	
19	describe('ZimmColourSwatch — link vs. span branch', () => {
20	  test('renders a router link (role radio) when href is provided', () => {
21	    wrap(
22	      <ZimmColourSwatch
23	        name="Ivory"
24	        imageUrl={IMAGE}
25	        href="/product/123?color=ivory"
26	        isSelected={false}
27	        isFocusable={true}
28	      />,
29	    );
30	    expect(screen.getByRole('radio', { name: 'Ivory' })).toBeInTheDocument();
31	  });
32	
33	  test('renders a button with radio role when href is absent (linkless path)', () => {
34	    wrap(<ZimmColourSwatch name="Ivory" imageUrl={IMAGE} isSelected={false} isFocusable={false} />);
35	    const swatch = screen.getByRole('radio', { name: 'Ivory' });
36	    expect(swatch.tagName).toBe('BUTTON');
37	    expect(swatch).toHaveAttribute('aria-checked', 'false');
38	    expect(swatch).toHaveAttribute('tabindex', '-1');
39	  });
40	
41	  test('calls onClick when linkless swatch is clicked', () => {
42	    const onClickMock = vi.fn();
43	    wrap(<ZimmColourSwatch name="Ivory" imageUrl={IMAGE} isSelected={false} isFocusable={true} onClick={onClickMock} />);
44	    screen.getByRole('radio', { name: 'Ivory' }).click();
45	    expect(onClickMock).toHaveBeenCalledTimes(1);
46	  });
47	});
48	
49	describe('ZimmColourSwatch — aria attributes (href branch only)', () => {
50	  test('aria-checked reflects isSelected', () => {
51	    wrap(<ZimmColourSwatch name="Navy" imageUrl={IMAGE} href="/p?color=navy" isSelected={true} isFocusable={true} />);
52	    expect(screen.getByRole('radio', { name: 'Navy' })).toHaveAttribute('aria-checked', 'true');
53	  });
54	
55	  test('aria-checked is false when not selected', () => {
56	    wrap(<ZimmColourSwatch name="Navy" imageUrl={IMAGE} href="/p?color=navy" isSelected={false} isFocusable={true} />);
57	    expect(screen.getByRole('radio', { name: 'Navy' })).toHaveAttribute('aria-checked', 'false');
58	  });
59	
60	  test('tabIndex is 0 when isFocusable is true', () => {
61	    wrap(<ZimmColourSwatch name="Navy" imageUrl={IMAGE} href="/p?color=navy" isSelected={false} isFocusable={true} />);
62	    expect(screen.getByRole('radio', { name: 'Navy' })).toHaveAttribute('tabindex', '0');
63	  });
64	
65	  test('tabIndex is -1 when isFocusable is false', () => {
66	    wrap(<ZimmColourSwatch name="Navy" imageUrl={IMAGE} href="/p?color=navy" isSelected={false} isFocusable={false} />);
67	    expect(screen.getByRole('radio', { name: 'Navy' })).toHaveAttribute('tabindex', '-1');
68	  });
69	});
70	
71	describe('ZimmColourSwatch — set position (aria-posinset / aria-setsize)', () => {
72	  test('propagates posInSet and setSize as ARIA attributes when provided', () => {
73	    wrap(
74	      <ZimmColourSwatch
75	        name="Navy"
76	        imageUrl={IMAGE}
77	        href="/p?color=navy"
78	        isSelected={false}
79	        isFocusable={true}
80	        posInSet={3}
81	        setSize={5}
82	      />,
83	    );
84	    const swatch = screen.getByRole('radio', { name: 'Navy' });
85	    expect(swatch).toHaveAttribute('aria-posinset', '3');
86	    expect(swatch).toHaveAttribute('aria-setsize', '5');
87	  });
88	
89	  test('omits aria-posinset/aria-setsize when props are absent', () => {
90	    wrap(<ZimmColourSwatch name="Navy" imageUrl={IMAGE} href="/p?color=navy" isSelected={false} isFocusable={true} />);
91	    const swatch = screen.getByRole('radio', { name: 'Navy' });
92	    // Absent props → no attribute (SR derives count from DOM — acceptable for non-paginated groups).
93	    expect(swatch).not.toHaveAttribute('aria-posinset');
94	    expect(swatch).not.toHaveAttribute('aria-setsize');
95	  });
96	});
97	
98	describe('ZimmColourSwatch — image', () => {
99	  test('image span carries the imageUrl as a backgroundImage CSS property', () => {
100	    wrap(
101	      <ZimmColourSwatch name="Coral" imageUrl={IMAGE} href="/p?color=coral" isSelected={false} isFocusable={true} />,
102	    );
103	    // emotion/Chakra applies __css as a CSS class in JSDOM, not as an inline style, so
104	    // element.style.backgroundImage is always ''. The data-image-url attribute is the test hook.
105	    const swatch = screen.getByTestId('colour-swatch');
106	    const imageSpan = swatch.firstElementChild as HTMLElement;
107	    expect(imageSpan.getAttribute('data-image-url')).toBe(IMAGE);
108	  });
109	
110	  test('does not set a raw CSS colour keyword via backgroundColor', () => {
111	    // backgroundColor from the colour name ("Ivory", "Bay Blue", ...) is deliberately absent.
112	    // See the comment in index.tsx for the three reasons this was dropped permanently.
113	    wrap(
114	      <ZimmColourSwatch name="Ivory" imageUrl={IMAGE} href="/p?color=ivory" isSelected={false} isFocusable={true} />,
115	    );
116	    const swatch = screen.getByTestId('colour-swatch');
117	    expect(swatch.style.backgroundColor).toBeFalsy();
118	  });
119	});
