import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';

const ZIMM_SIZE_CHIP_RECIPE = 'ZimmSizeChip';

type ZimmSizeChipProps = {
  /** Underlying size value used for selection/comparison (e.g. an SFCC variation value). */
  value: string;
  /** Visible/accessible label rendered inside the chip (e.g. "S", "M", "42"). */
  label: string;
  /** Whether this is the currently selected size. */
  isSelected: boolean;
  /**
   * Whether this size is unavailable. Sets the real native `disabled` attribute so the chip is
   * genuinely inert for both mouse and assistive tech, not just visually greyed.
   */
  isDisabled?: boolean;
  /**
   * Whether this chip is reachable via Tab (`tabIndex={0}`) vs. removed from the tab order
   * (`tabIndex={-1}`) — the caller (ZimmSizeChipGroup) drives a roving tabindex across the row.
   * Mirrors ZimmColourSwatch's identical prop, for the identical reason.
   */
  isFocusable: boolean;
  /** Selection callback, called with `value` on click. Never called when `isDisabled` is true. */
  onSelect: (value: string) => void;
};

/**
 * Atom — a single size option in a PDP size-chip row: a 28x28 button with radio semantics (one
 * selection out of the group). Purely presentational — no data-fetching hook, no keyboard
 * orchestration (that lives in the parent ZimmSizeChipGroup, matching the ZimmColourSwatch /
 * ZimmColourSwatchGroup split).
 */
export const ZimmSizeChip = ({ value, label, isSelected, isDisabled, isFocusable, onSelect }: ZimmSizeChipProps) => {
  const styles = useMultiStyleConfig(ZIMM_SIZE_CHIP_RECIPE, { selected: isSelected, disabled: isDisabled });

  return (
    <chakra.button
      __css={styles.chip}
      type="button"
      role="radio"
      aria-checked={isSelected}
      disabled={isDisabled}
      tabIndex={isFocusable ? 0 : -1}
      data-testid="size-chip"
      data-size-value={value}
      onClick={() => {
        // Belt-and-braces: the native `disabled` attribute above already prevents the browser
        // from ever dispatching this click, but stating the invariant explicitly means a reader
        // doesn't have to recall that fact to trust onSelect can't fire for a disabled chip.
        if (!isDisabled) onSelect(value);
      }}
    >
      {label}
    </chakra.button>
  );
};

export type { ZimmSizeChipProps };
export default ZimmSizeChip;

import type { SystemStyleObject } from '@chakra-ui/react';

/** State the atom feeds in so the recipe can resolve the Figma state cascade. */
type ZimmSizeChipStyleProps = {
  selected?: boolean;
  disabled?: boolean;
};

/**
 * Border colour precedence: disabled > selected > default — same "no state stacking" shape as
 * zimmTextInput.css.ts's resolveBorderColour.
 */
const resolveBorderColour = ({ selected, disabled }: ZimmSizeChipStyleProps): string => {
  if (disabled) return 'var(--zimm-color-border-secondary)';
  if (selected) return 'var(--zimm-color-text-default)';
  return 'var(--zimm-color-border-forms)'; // same "field border default" token zimmTextInput.css.ts uses
};

const resolveBackgroundColour = ({ selected, disabled }: ZimmSizeChipStyleProps): string => {
  if (disabled) return 'transparent';
  if (selected) return 'var(--zimm-color-text-default)';
  return 'transparent';
};

const resolveTextColour = ({ selected, disabled }: ZimmSizeChipStyleProps): string => {
  if (disabled) return 'var(--zimm-color-text-muted)';
  if (selected) return 'var(--zimm-color-text-inverse)';
  return 'var(--zimm-color-text-default)';
};

/**
 * Recipe for the PDP size chip atom — a single 28x28 (--zimm-scale-700) size option, read
 * directly off the size-chip Figma component set (node 40003038:125876) for this exact
 * component's dimensions and state list. Four Figma-defined states — Default / Selected /
 * Focus / Disabled — resolved by the three `resolveXxxColour` helpers above and the
 * `_focusVisible` block below. Hover and Active/pressed are NOT part of that variant set, so
 * neither is implemented here — same "don't invent an unspecified visual state" precedent as
 * zimmColourSwatchGroup.css.ts's `pageButton` part.
 *
 * The exact fill/border colour pairing per state is this file's own best-effort reading of the
 * "Default / Selected / Disabled" state names against already-established Zimmermann tokens
 * (border-forms for a default field-style outline, a text-default fill for the selected state
 * mirroring Button's own primary variant, text-muted/border-secondary for disabled mirroring
 * Button's/ZimmTextInput's own disabled treatment) — no literal per-state hex breakdown was
 * supplied for this component, so this pairing is a reasonable inference from precedent, not a
 * pixel-confirmed Figma export. Flag for UI-designer confirmation if it doesn't match.
 */
export const ZimmSizeChip = {
  parts: ['chip'],
  baseStyle: (props: ZimmSizeChipStyleProps): Record<string, SystemStyleObject> => ({
    chip: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      width: 'var(--zimm-scale-700)', // 28px
      height: 'var(--zimm-scale-700)', // 28px
      border: 'var(--zimm-border-width-default) solid',
      borderColor: resolveBorderColour(props),
      background: resolveBackgroundColour(props),
      color: resolveTextColour(props),
      textStyle: 'buttonSm',
      padding: 0,
      outline: 'none',
      cursor: props.disabled ? 'not-allowed' : 'pointer',
      _focusVisible: {
        outline: 'var(--zimm-focus-ring)',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },
  }),
};

import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { expect, userEvent, within } from 'storybook/test';
import React from 'react';
import { ZimmSizeChip } from './index';

const meta: Meta<typeof ZimmSizeChip> = {
  title: 'Commerce/ZimmSizeChip',
  component: ZimmSizeChip,
  parameters: { layout: 'centered' },
  // role="radiogroup" satisfies the ARIA ownership requirement for role="radio" elements
  // rendered in isolation — the molecule normally provides this via its chip row.
  decorators: [
    (Story) => (
      <div role="radiogroup" aria-label="Size">
        <Story />
      </div>
    ),
  ],
};

export default meta;
type Story = StoryObj<typeof ZimmSizeChip>;

/** Unselected, enabled chip. */
export const Default: Story = {
  args: {
    value: 'm',
    label: 'M',
    isSelected: false,
    isFocusable: true,
    onSelect: () => {},
  },
};

/** Selected chip — filled treatment, distinct from Default. */
export const Selected: Story = {
  args: {
    value: 'm',
    label: 'M',
    isSelected: true,
    isFocusable: true,
    onSelect: () => {},
  },
};

/** Disabled chip — genuinely inert (native `disabled` attribute), muted treatment. */
export const Disabled: Story = {
  args: {
    value: 'm',
    label: 'M',
    isSelected: false,
    isDisabled: true,
    isFocusable: false,
    onSelect: () => {},
  },
};

/**
 * Focus state — demonstrated via a real Tab keypress rather than a static prop, since
 * `:focus-visible` cannot be set declaratively. Storybook runs in a real browser (unlike
 * Vitest/jsdom), so this exercises the genuine CSS state.
 */
export const Focus: Story = {
  args: {
    value: 'm',
    label: 'M',
    isSelected: false,
    isFocusable: true,
    onSelect: () => {},
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const chip = canvas.getByRole('radio', { name: 'M' });
    await userEvent.tab();
    await expect(chip).toHaveFocus();
  },
};

import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ZimmSizeChip } from './index';

// Provide a minimal Chakra context so chakra() and useMultiStyleConfig resolve without needing
// the full Zimmermann theme (which would require the ZimmSizeChip recipe to be registered
// before these tests are even loaded).
vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return { ...actual, useMultiStyleConfig: () => ({ chip: {} }) };
});

describe('ZimmSizeChip — element and radio semantics', () => {
  test('renders a native <button> with role radio', () => {
    render(<ZimmSizeChip value="m" label="M" isSelected={false} isFocusable={true} onSelect={vi.fn()} />);
    const chip = screen.getByRole('radio', { name: 'M' });
    expect(chip.tagName).toBe('BUTTON');
  });

  test('label text is the visible/accessible content', () => {
    render(<ZimmSizeChip value="42" label="42" isSelected={false} isFocusable={true} onSelect={vi.fn()} />);
    expect(screen.getByRole('radio', { name: '42' })).toHaveTextContent('42');
  });
});

describe('ZimmSizeChip — aria-checked reflects isSelected', () => {
  test('aria-checked is true when selected', () => {
    render(<ZimmSizeChip value="m" label="M" isSelected={true} isFocusable={true} onSelect={vi.fn()} />);
    expect(screen.getByRole('radio', { name: 'M' })).toHaveAttribute('aria-checked', 'true');
  });

  test('aria-checked is false when not selected', () => {
    render(<ZimmSizeChip value="m" label="M" isSelected={false} isFocusable={true} onSelect={vi.fn()} />);
    expect(screen.getByRole('radio', { name: 'M' })).toHaveAttribute('aria-checked', 'false');
  });
});

describe('ZimmSizeChip — roving tabindex', () => {
  test('tabIndex is 0 when isFocusable is true', () => {
    render(<ZimmSizeChip value="m" label="M" isSelected={false} isFocusable={true} onSelect={vi.fn()} />);
    expect(screen.getByRole('radio', { name: 'M' })).toHaveAttribute('tabindex', '0');
  });

  test('tabIndex is -1 when isFocusable is false', () => {
    render(<ZimmSizeChip value="m" label="M" isSelected={false} isFocusable={false} onSelect={vi.fn()} />);
    expect(screen.getByRole('radio', { name: 'M' })).toHaveAttribute('tabindex', '-1');
  });
});

describe('ZimmSizeChip — selection', () => {
  test('calls onSelect with the chip value when clicked', () => {
    const onSelect = vi.fn();
    render(<ZimmSizeChip value="m" label="M" isSelected={false} isFocusable={true} onSelect={onSelect} />);
    screen.getByRole('radio', { name: 'M' }).click();
    expect(onSelect).toHaveBeenCalledTimes(1);
    expect(onSelect).toHaveBeenCalledWith('m');
  });
});

describe('ZimmSizeChip — disabled', () => {
  test('sets the real native disabled attribute', () => {
    render(
      <ZimmSizeChip value="m" label="M" isSelected={false} isFocusable={true} isDisabled onSelect={vi.fn()} />,
    );
    expect(screen.getByRole('radio', { name: 'M' })).toBeDisabled();
  });

  test('never calls onSelect when a disabled chip is clicked', () => {
    const onSelect = vi.fn();
    render(
      <ZimmSizeChip value="m" label="M" isSelected={false} isFocusable={true} isDisabled onSelect={onSelect} />,
    );
    screen.getByRole('radio', { name: 'M' }).click();
    expect(onSelect).not.toHaveBeenCalled();
  });
});

import React, { useEffect, useRef, useState } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { defineMessages, useIntl } from 'react-intl';
import { ZimmSizeChip } from '../../atoms/zimmSizeChip';

const messages = defineMessages({
  groupLabel: { id: 'size_chips.group.label', defaultMessage: 'Select a size' },
});

const ZIMM_SIZE_CHIP_GROUP_RECIPE = 'ZimmSizeChipGroup';

/** One selectable size as the molecule expects it — pre-mapped from the raw SFCC shape. */
export type ZimmSizeChipValue = {
  value: string;
  label: string;
  /**
   * Mirrors SFCC's orderable/stock flag for this size. Unlike ZimmColourSwatchGroup's colours
   * (withheld entirely when unavailable), an unavailable size is shown disabled so the shopper
   * can still see the full size run — the size-chip Figma component set includes a dedicated
   * Disabled state for exactly this.
   */
  isDisabled?: boolean;
};

type ZimmSizeChipGroupProps = {
  values: ZimmSizeChipValue[];
  /** Currently selected size value (from URL / variation params). */
  selectedValue?: string;
  /**
   * Selection callback. Called on click and on arrow-key navigation landing on a new chip.
   * Never called for a disabled size under any input method.
   */
  onSelect?: (value: string) => void;
};

/** Index of the first non-disabled entry in `list`, or -1 when every entry is disabled. */
const firstEnabledIndex = (list: ZimmSizeChipValue[]): number => list.findIndex((v) => !v.isDisabled);

/**
 * The roving-tabindex/selection target: the selected value's index when it is itself enabled,
 * else the first enabled entry. Kept as a standalone pure function (rather than a closure over
 * component props) so the effect below can list its real inputs (`list`, `selected`) directly
 * as dependencies, with nothing left out for eslint's exhaustive-deps to flag.
 */
const computeFocusIndex = (list: ZimmSizeChipValue[], selected: string | undefined): number => {
  const selectedIndex = list.findIndex((v) => v.value === selected);
  return selectedIndex >= 0 && !list[selectedIndex].isDisabled ? selectedIndex : firstEnabledIndex(list);
};

/**
 * Molecule — the full PDP size-chip group: a `[role=radiogroup]` row of ZimmSizeChip atoms with
 * roving tabindex and keyboard navigation, adapted from ZimmColourSwatchGroup's
 * handleSwatchesKeyDown for a row with no pagination and a real per-chip disabled state (arrow
 * navigation must skip a disabled chip rather than land on or select it).
 *
 * When exactly one size is offered, the size-chip Figma component set's other Type applies: a
 * single non-interactive label renders instead of a one-item radiogroup — a genuinely
 * different, non-interactive component, not a radiogroup with one item.
 */
export const ZimmSizeChipGroup = ({ values, selectedValue, onSelect }: ZimmSizeChipGroupProps) => {
  const intl = useIntl();
  const groupLabel = intl.formatMessage(messages.groupLabel);
  const styles = useMultiStyleConfig(ZIMM_SIZE_CHIP_GROUP_RECIPE, {});

  // Roving-tabindex target, tracked as its own state rather than derived fresh every render —
  // arrow-key navigation updates it directly so the tab stop (and the imperative focus below)
  // moves within a single interaction, without depending on a controlling parent re-passing a
  // new `selectedValue` prop first.
  const [focusIndex, setFocusIndex] = useState(() => computeFocusIndex(values, selectedValue));

  // Re-sync the roving tab stop whenever the selected value or the list itself changes from
  // outside this component (e.g. a controlling page changing colour, which can change which
  // sizes are disabled).
  useEffect(() => {
    setFocusIndex(computeFocusIndex(values, selectedValue));
  }, [values, selectedValue]);

  const radiogroupRef = useRef<HTMLDivElement>(null);
  const shouldRefocus = useRef(false);

  // Imperative focus after arrow-key navigation — mirrors ZimmColourSwatchGroup's own
  // hasNavigated-ref pattern, adapted to fire off this component's own focusIndex state
  // directly rather than waiting on a selectedValue round-trip through a controlling parent.
  useEffect(() => {
    if (!shouldRefocus.current) return;
    shouldRefocus.current = false;
    const target = values[focusIndex];
    if (!target) return;
    const el = radiogroupRef.current?.querySelector(`[data-size-value="${target.value}"]`);
    (el as HTMLElement | null)?.focus();
  }, [focusIndex, values]);

  const selectIndex = (index: number, { refocus }: { refocus: boolean }) => {
    const target = values[index];
    if (!target || target.isDisabled) return;
    setFocusIndex(index);
    shouldRefocus.current = refocus;
    onSelect?.(target.value);
  };

  const handleChipsKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
    e.preventDefault();
    if (values.length === 0) return;

    // Derive current index from the focused element's data-size-value — a unique value
    // identity that survives duplicate display labels, same reasoning as
    // zimmColourSwatchGroup's own data-swatch-value lookup.
    const focusedValue = (document.activeElement as HTMLElement | null)?.getAttribute('data-size-value');
    const focusedIndex = focusedValue ? values.findIndex((v) => v.value === focusedValue) : -1;
    const currentIndex = focusedIndex >= 0 ? focusedIndex : focusIndex;
    if (currentIndex < 0) return; // every chip disabled — nothing to navigate from

    const step = e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : -1;

    let nextIndex = currentIndex;
    for (let attempt = 0; attempt < values.length; attempt += 1) {
      nextIndex = (nextIndex + step + values.length) % values.length;
      if (!values[nextIndex].isDisabled) {
        selectIndex(nextIndex, { refocus: true });
        return;
      }
    }
    // Looped through every chip and found none enabled — nothing to do.
  };

  // Nothing offered — suppress the group entirely rather than render an empty radiogroup, same
  // "nothing to show" precedent as zimmColourSwatchGroup's own offered.length === 0 guard.
  if (values.length === 0) return null;

  if (values.length === 1) {
    return (
      <chakra.span __css={styles.oneSize} data-testid="size-chip-one-size">
        {values[0].label}
      </chakra.span>
    );
  }

  return (
    <chakra.div
      role="radiogroup"
      aria-label={groupLabel}
      ref={radiogroupRef}
      __css={styles.radiogroup}
      onKeyDown={handleChipsKeyDown}
    >
      {values.map((v, i) => (
        <ZimmSizeChip
          key={v.value}
          value={v.value}
          label={v.label}
          isSelected={v.value === selectedValue}
          isDisabled={v.isDisabled}
          isFocusable={i === focusIndex}
          onSelect={() => selectIndex(i, { refocus: false })}
        />
      ))}
    </chakra.div>
  );
};

export default ZimmSizeChipGroup;

import type { SystemStyleObject } from '@chakra-ui/react';

/**
 * Recipe for the PDP size-chip group. Two mutually-exclusive root renders, matching the two
 * "Type" variants of the size-chip Figma component set (node 40003066:34868):
 *   - `radiogroup` — the multi-size row (the default Type, 208x28 in Figma) — lays out
 *     ZimmSizeChip atoms in a row; each chip's own fill/border/focus styling stays in the
 *     sibling ZimmSizeChip atom's own recipe, this part is layout only.
 *   - `oneSize` — the single non-interactive label shown when only one size is offered (the
 *     other Type, 65x28 in Figma) — a genuinely different, non-interactive component, not a
 *     radiogroup with one item.
 */
export const ZimmSizeChipGroup = {
  parts: ['radiogroup', 'oneSize'],
  baseStyle: (): Record<string, SystemStyleObject> => ({
    radiogroup: {
      display: 'flex',
      alignItems: 'center',
      // No inter-chip gap value confirmed for this exact node — left at the flex default (no
      // `gap` declared) rather than invented, same precedent as
      // zimmColourSwatchGroup.css.ts's `pagination` part.
    },

    oneSize: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      // The non-interactive single-label footprint from the size-chip Figma component set's
      // other Type — no matching width-scale token for 65px; height reuses the same
      // --zimm-scale-700 (28px) the ZimmSizeChip atom's own `chip` part uses, since it is the
      // same row height as the interactive variant.
      // audit-allow: 65px — no foundation width token exists for this exact non-interactive
      // label size
      width: '65px',
      height: 'var(--zimm-scale-700)',
      textStyle: 'buttonSm',
      color: 'var(--zimm-color-text-default)',
    },
  }),
};

import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { expect, userEvent, within } from 'storybook/test';
import React, { useState } from 'react';
import { ZimmSizeChipGroup } from './index';
import type { ZimmSizeChipValue } from './index';

const meta: Meta<typeof ZimmSizeChipGroup> = {
  title: 'Commerce/ZimmSizeChipGroup',
  component: ZimmSizeChipGroup,
  parameters: { layout: 'padded' },
};

export default meta;
type Story = StoryObj<typeof ZimmSizeChipGroup>;

const SIZES: ZimmSizeChipValue[] = [
  { value: 'xs', label: 'XS' },
  { value: 's', label: 'S' },
  { value: 'm', label: 'M' },
  { value: 'l', label: 'L' },
  { value: 'xl', label: 'XL' },
];

/** Multi-size row, nothing selected. */
export const Default: Story = {
  args: {
    values: SIZES,
  },
};

/** A size pre-selected — its chip renders with the selected treatment and is the tab stop. */
export const WithSelection: Story = {
  args: {
    values: SIZES,
    selectedValue: 'm',
  },
};

/** One size unavailable — shown disabled (not withheld), so the full size run stays visible. */
export const WithDisabledSize: Story = {
  args: {
    values: [
      { value: 'xs', label: 'XS' },
      { value: 's', label: 'S', isDisabled: true },
      { value: 'm', label: 'M' },
      { value: 'l', label: 'L' },
    ],
    selectedValue: 'm',
  },
};

/** The size-chip Figma component set's other Type — a single non-interactive label, not a
 *  one-item radiogroup. */
export const OneSize: Story = {
  args: {
    values: [{ value: 'os', label: 'One Size' }],
  },
};

const KeyboardNavigationExample = () => {
  const [selectedValue, setSelectedValue] = useState<string | undefined>('xs');
  return <ZimmSizeChipGroup values={SIZES} selectedValue={selectedValue} onSelect={setSelectedValue} />;
};

/** Arrow-key navigation — ArrowRight moves both the roving tab stop and the selection. */
export const KeyboardNavigation: Story = {
  render: () => <KeyboardNavigationExample />,
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const first = canvas.getByRole('radio', { name: 'XS' });
    await userEvent.click(first);
    await userEvent.keyboard('{ArrowRight}');
    const second = canvas.getByRole('radio', { name: 'S' });
    await expect(second).toHaveFocus();
    await expect(second).toHaveAttribute('aria-checked', 'true');
  },
};

import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { IntlProvider } from 'react-intl';
import { ZimmSizeChipGroup } from './index';
import type { ZimmSizeChipValue } from './index';

// ZimmSizeChip's own recipe also needs useMultiStyleConfig — mock both layers so tests don't
// require a full Chakra theme. The mocked shape only needs to cover this molecule's own two
// parts; the atom's `styles.chip` simply resolves to undefined under it, which is a legal,
// harmless __css value (see zimmColourSwatchGroup's identical test-file precedent).
vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return { ...actual, useMultiStyleConfig: () => ({ radiogroup: {}, oneSize: {} }) };
});

const wrap = (ui: React.ReactElement) =>
  render(
    <IntlProvider locale="en" defaultLocale="en">
      {ui}
    </IntlProvider>,
  );

const group = () => screen.getByRole('radiogroup', { name: 'Select a size' });
const radios = () => screen.getAllByRole('radio');

const val = (value: string, label: string, over: Partial<ZimmSizeChipValue> = {}): ZimmSizeChipValue => ({
  value,
  label,
  ...over,
});

const FOUR = [val('xs', 'XS'), val('s', 'S'), val('m', 'M'), val('l', 'L')];

describe('ZimmSizeChipGroup — radiogroup semantics', () => {
  test('renders role=radiogroup with an aria-label describing the group', () => {
    wrap(<ZimmSizeChipGroup values={FOUR} />);
    expect(group()).toBeInTheDocument();
  });

  test('renders every offered size as a radio', () => {
    wrap(<ZimmSizeChipGroup values={FOUR} />);
    expect(radios()).toHaveLength(4);
  });
});

describe('ZimmSizeChipGroup — One Size', () => {
  test('renders a single non-interactive label, no radiogroup, no radio', () => {
    wrap(<ZimmSizeChipGroup values={[val('os', 'One Size')]} />);
    expect(screen.getByText('One Size')).toBeInTheDocument();
    expect(screen.queryByRole('radiogroup')).not.toBeInTheDocument();
    expect(screen.queryAllByRole('radio')).toHaveLength(0);
  });

  test('clicking around the One Size label calls nothing', async () => {
    const onSelect = vi.fn();
    const user = userEvent.setup();
    wrap(<ZimmSizeChipGroup values={[val('os', 'One Size')]} onSelect={onSelect} />);
    await user.click(screen.getByText('One Size'));
    expect(onSelect).not.toHaveBeenCalled();
  });
});

describe('ZimmSizeChipGroup — no offered sizes', () => {
  test('renders nothing for an empty values array', () => {
    const { container } = wrap(<ZimmSizeChipGroup values={[]} />);
    expect(container.firstChild).toBeNull();
  });
});

describe('ZimmSizeChipGroup — roving tabindex', () => {
  test('exposes exactly one tab stop matching the selected size', () => {
    wrap(<ZimmSizeChipGroup values={FOUR} selectedValue="m" />);
    const stops = within(group())
      .getAllByRole('radio')
      .filter((el) => el.getAttribute('tabindex') === '0');
    expect(stops).toHaveLength(1);
    expect(stops[0]).toHaveTextContent('M');
  });

  test('falls back to the first size as the tab stop when nothing is selected', () => {
    wrap(<ZimmSizeChipGroup values={FOUR} />);
    const stops = within(group())
      .getAllByRole('radio')
      .filter((el) => el.getAttribute('tabindex') === '0');
    expect(stops).toHaveLength(1);
    expect(stops[0]).toHaveTextContent('XS');
  });

  test('falls back to the first ENABLED size when the first size is disabled', () => {
    const values = [val('xs', 'XS', { isDisabled: true }), val('s', 'S'), val('m', 'M')];
    wrap(<ZimmSizeChipGroup values={values} />);
    const stops = within(group())
      .getAllByRole('radio')
      .filter((el) => el.getAttribute('tabindex') === '0');
    expect(stops).toHaveLength(1);
    expect(stops[0]).toHaveTextContent('S');
  });

  test('a disabled chip is never the roving tab stop, even when two are adjacent', () => {
    const values = [val('xs', 'XS', { isDisabled: true }), val('s', 'S', { isDisabled: true }), val('m', 'M')];
    wrap(<ZimmSizeChipGroup values={values} />);
    const stops = within(group())
      .getAllByRole('radio')
      .filter((el) => el.getAttribute('tabindex') === '0');
    expect(stops).toHaveLength(1);
    expect(stops[0]).toHaveTextContent('M');
  });

  test('tab stop updates and real DOM focus moves after ArrowRight', async () => {
    const user = userEvent.setup();
    wrap(<ZimmSizeChipGroup values={FOUR} selectedValue="xs" onSelect={vi.fn()} />);
    radios()[0].focus();
    await user.keyboard('{ArrowRight}');

    const stops = within(group())
      .getAllByRole('radio')
      .filter((el) => el.getAttribute('tabindex') === '0');
    expect(stops).toHaveLength(1);
    expect(stops[0]).toHaveTextContent('S');
    expect(screen.getByRole('radio', { name: 'S' })).toHaveFocus();
  });
});

describe('ZimmSizeChipGroup — arrow key navigation', () => {
  test('ArrowRight moves to the next size and calls onSelect', async () => {
    const onSelect = vi.fn();
    const user = userEvent.setup();
    wrap(<ZimmSizeChipGroup values={FOUR} selectedValue="xs" onSelect={onSelect} />);
    radios()[0].focus();
    await user.keyboard('{ArrowRight}');
    expect(onSelect).toHaveBeenCalledWith('s');
  });

  test('ArrowDown behaves the same as ArrowRight', async () => {
    const onSelect = vi.fn();
    const user = userEvent.setup();
    wrap(<ZimmSizeChipGroup values={FOUR} selectedValue="xs" onSelect={onSelect} />);
    radios()[0].focus();
    await user.keyboard('{ArrowDown}');
    expect(onSelect).toHaveBeenCalledWith('s');
  });

  test('ArrowLeft moves to the previous size and calls onSelect', async () => {
    const onSelect = vi.fn();
    const user = userEvent.setup();
    wrap(<ZimmSizeChipGroup values={FOUR} selectedValue="m" onSelect={onSelect} />);
    radios()[2].focus(); // 'm'
    await user.keyboard('{ArrowLeft}');
    expect(onSelect).toHaveBeenCalledWith('s');
  });

  test('ArrowUp behaves the same as ArrowLeft', async () => {
    const onSelect = vi.fn();
    const user = userEvent.setup();
    wrap(<ZimmSizeChipGroup values={FOUR} selectedValue="m" onSelect={onSelect} />);
    radios()[2].focus();
    await user.keyboard('{ArrowUp}');
    expect(onSelect).toHaveBeenCalledWith('s');
  });

  test('ArrowRight wraps from the last size to the first', async () => {
    const onSelect = vi.fn();
    const user = userEvent.setup();
    wrap(<ZimmSizeChipGroup values={FOUR} selectedValue="l" onSelect={onSelect} />);
    radios()[3].focus(); // 'l', last
    await user.keyboard('{ArrowRight}');
    expect(onSelect).toHaveBeenCalledWith('xs');
  });

  test('ArrowLeft wraps from the first size to the last', async () => {
    const onSelect = vi.fn();
    const user = userEvent.setup();
    wrap(<ZimmSizeChipGroup values={FOUR} selectedValue="xs" onSelect={onSelect} />);
    radios()[0].focus();
    await user.keyboard('{ArrowLeft}');
    expect(onSelect).toHaveBeenCalledWith('l');
  });
});

describe('ZimmSizeChipGroup — disabled sizes are skipped by arrow navigation', () => {
  const values = [val('xs', 'XS'), val('s', 'S', { isDisabled: true }), val('m', 'M')];

  test('ArrowRight jumps over a disabled size in the middle of the list', async () => {
    const onSelect = vi.fn();
    const user = userEvent.setup();
    wrap(<ZimmSizeChipGroup values={values} selectedValue="xs" onSelect={onSelect} />);
    radios()[0].focus();
    await user.keyboard('{ArrowRight}');
    expect(onSelect).toHaveBeenCalledWith('m');
    expect(onSelect).not.toHaveBeenCalledWith('s');
  });

  test('ArrowLeft jumps over a disabled size in the middle of the list', async () => {
    const onSelect = vi.fn();
    const user = userEvent.setup();
    wrap(<ZimmSizeChipGroup values={values} selectedValue="m" onSelect={onSelect} />);
    radios()[2].focus();
    await user.keyboard('{ArrowLeft}');
    expect(onSelect).toHaveBeenCalledWith('xs');
    expect(onSelect).not.toHaveBeenCalledWith('s');
  });
});

describe('ZimmSizeChipGroup — click selection', () => {
  test('calls onSelect with the clicked size value', async () => {
    const onSelect = vi.fn();
    const user = userEvent.setup();
    wrap(<ZimmSizeChipGroup values={FOUR} onSelect={onSelect} />);
    await user.click(screen.getByRole('radio', { name: 'M' }));
    expect(onSelect).toHaveBeenCalledWith('m');
  });

  test('never calls onSelect when clicking a disabled size', async () => {
    const onSelect = vi.fn();
    const user = userEvent.setup();
    const values = [val('xs', 'XS'), val('s', 'S', { isDisabled: true })];
    wrap(<ZimmSizeChipGroup values={values} onSelect={onSelect} />);
    await user.click(screen.getByRole('radio', { name: 'S' }));
    expect(onSelect).not.toHaveBeenCalled();
  });
});

